        V("malaki", "malakí", "big", say="ma-la-KI", pos="adj", group="adjs"),
        V("malamig", "malamíg", "cold", say="ma-la-MIG", pos="adj", group="adjs"),
        V("bago", "bágo", "new", say="BA-go", pos="adj", group="adjs"),
